using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Data;
using System.Drawing;
using System.Text;
using System.Windows.Forms;
using DevExpress.XtraEditors;
using System.Threading;
using Libs;
using Global;
using GeneralObject;
using GeneralService;


namespace General
{
    public partial class frmCostSource : FormBase, IForm
    {
        #region Consts
        public const string PERMISSION_ADD = "GEN_CostSource_Add";
        public const string PERMISSION_DELETE = "GEN_CostSource_Delete";
        public const string PERMISSION_EDIT = "GEN_CostSource_Edit";
        public const string PERMISSION_VIEW = "GEN_CostSource_View";

        #endregion

        #region Variables

        DataTable dtbData;
        bool bolIsRefresh = false;

        #endregion

        #region IForm Members

        private static frmCostSource _instance = null;

        public static frmCostSource Instance
        {
            get
            {
                if (_instance == null)
                    _instance = new frmCostSource();
                return _instance;
            }
        }

        public void Run(bool isShowDialog)
        {
            FormManager.Run(Instance, isShowDialog);
        }

        #endregion


        public frmCostSource()
        {
            InitializeComponent();
        }

        #region Support Functions

        private void CheckPermission()
        {
            gvData.OptionsView.NewItemRowPosition = UserSession.HasPermission(PERMISSION_ADD) ? DevExpress.XtraGrid.Views.Grid.NewItemRowPosition.Top : DevExpress.XtraGrid.Views.Grid.NewItemRowPosition.None;
        }

        public void LoadReferenceData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadReferenceData));
            else
            {
            }
        }

        public void LoadData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadData));
            else
            {
                dtbData = new GEN_CostSource().Search();
                if (dtbData != null)
                {
                    gcData.DataSource = dtbData;
                    SystemService.SYS_GridColumnService.InitGridColumn(gvData, "GEN_CostSource", bolIsRefresh);
                    bolIsRefresh = false;
                }
                else
                {
                    ErrorManager.Error("Việc lấy thông tin bị lỗi!");
                }
            }
        }


        /// <summary>
        /// Xóa từng dòng được chọn, bị lỗi chỗ nào thì ngưng chỗ ấy lại
        /// </summary>
        /// <returns></returns>
        private bool DeleteData()
        {
            GEN_CostSource objCostSource = new GEN_CostSource();
            int[] arrRowIndex = gvData.GetSelectedRows();
            for (int i = arrRowIndex.Length - 1; i >= 0; i--)
            {
                DataRow drw = gvData.GetDataRow(arrRowIndex[i]);
                if (drw != null)
                {
                    if (drw.RowState != DataRowState.Added)
                    {
                        if (!objCostSource.Delete(Convert.ToInt32(drw[GEN_CostSource.C_CostSourceID])))
                        {
                            ErrorManager.Error("Dữ liệu đang sử dụng bạn không xóa được!");
                            return false;
                        }
                    }
                    gvData.DeleteRow(arrRowIndex[i]);
                }
            }
            return true;
        }

        /// <summary>
        /// Save dữ liệu ở lưới
        /// </summary>
        private bool SaveData()
        {
            if (dtbData != null)
            {
                GEN_CostSource item0 = new GEN_CostSource();
                item0.BeginTransaction();
                foreach (DataRow drw in dtbData.Rows)
                {
                    if (drw.RowState != DataRowState.Deleted)
                    {
                        GEN_CostSource item = new GEN_CostSource();
                        item.IDB = item0.IDB;
                        if (item.Parse(drw))
                        {
                            if (drw.RowState == DataRowState.Added)
                            {
                                item.CreatedUser = UserSession.Username;
                                if (!item.Add())
                                {
                                    item0.RollBackTransaction();
                                    ErrorManager.Error("Việc thêm thông tin bị lỗi!");
                                    return false;
                                }
                            }
                            else if (drw.RowState == DataRowState.Modified)
                            {
                                item.UpdatedUser = UserSession.Username;
                                if (!item.Update())
                                {
                                    item0.RollBackTransaction();
                                    ErrorManager.Error("Việc cập nhật thông tin bị lỗi!");
                                    return false;
                                }
                            }
                        }
                    }
                }
                item0.CommitTransaction();
                return true;
            }
            return true;
        }

        private string CheckValidate(DataRow drw)
        {
            if (drw == null)
                return "";
            GEN_CostSource item = new GEN_CostSource();
            if (item.Parse(drw))
            {
                if (item.CostSourceCode == "" || item.CostSourceCode == null)
                    return "Bạn phải nhập mã nguồn kinh phí!";
                if (item.CostSourceName == "" || item.CostSourceName == null)
                    return "Bạn phải nhập tên nguồn kinh phí!";
            }
            return "";
        }

        #endregion

        #region Form Actions

        private void frmCostSource_Load(object sender, EventArgs e)
        {
            new Thread(LoadData).Start();
            new Thread(LoadReferenceData).Start();
            CheckPermission();
            SetToolTip();
        }

        private void btnClose_Click(object sender, EventArgs e)
        {
            this.Close();
        }

        private void gvData_SelectionChanged(object sender, DevExpress.Data.SelectionChangedEventArgs e)
        {
            mnuItemDelete.Enabled = btnDelete.Enabled = gvData.SelectedRowsCount > 0 && UserSession.HasPermission(PERMISSION_DELETE);
        }

        private void btnDelete_Click(object sender, EventArgs e)
        {
            if (MessageManager.Confirm("Bạn thực sự muốn xóa những dữ liệu này?") == DialogResult.Yes)
            {
                DeleteData();
                GEN_CostSourceService.HaveNewData = true;
            }
        }

        private void btnSave_Click(object sender, EventArgs e)
        {
            if (SaveData())
            {
                new Thread(LoadData).Start();
                GEN_CostSourceService.HaveNewData = true;
                btnSave.Enabled = mnuItemSave.Enabled = false;
            }
        }

        private void mnuItemRefresh_Click(object sender, EventArgs e)
        {
            bolIsRefresh = true;
            new Thread(LoadData).Start();
            new Thread(LoadReferenceData).Start();
        }

        private void mnuItemExportToExcel_Click(object sender, EventArgs e)
        {
            gvData.QuickExportToExcel();
        }

        private void frmCostSource_KeyDown(object sender, KeyEventArgs e)
        {
            switch (e.KeyData)
            {
                case Keys.F1:
                    this.ShowToolTip();
                    break;

                case Keys.F4:
                    if (btnDelete.Enabled)
                        btnDelete_Click(sender, null);
                    break;
                case Keys.F5:
                    mnuItemRefresh_Click(sender, null);
                    break;
                case Keys.F6:
                    if (mnuItemSave.Enabled)
                        btnSave_Click(sender, null);
                    break;
                case Keys.F7:
                    break;
                case Keys.F8:
                    gvData.AddNewRow();
                    break;
                case Keys.Escape:
                    break;
            }
        }

        #endregion

        #region Grid Actions

        private void gvData_ShowingEditor(object sender, CancelEventArgs e)
        {
            if (!gvData.IsNewItemRow(gvData.FocusedRowHandle))
            {
                if (!UserSession.HasPermission(PERMISSION_EDIT))
                    e.Cancel = true;
            }
        }

        private void gvData_ValidatingEditor(object sender, DevExpress.XtraEditors.Controls.BaseContainerValidateEditorEventArgs e)
        {
            if (gvData.FocusedRowHandle == -999997)
                return;
            string strError = "";
            switch (gvData.FocusedColumn.FieldName)
            {
                case GEN_CostSource.C_CostSourceCode:
                    e.Valid = Libs.ValidationHelper.ValidateEmptyString(e.Value, "Mã không được bỏ trống!", ref strError);
                    if (e.Valid == true)
                    {
                        if (gvData.SearchRow(GEN_CostSource.C_CostSourceCode, e.Value, gvData.FocusedRowHandle) >= 0)
                        {
                            strError = "Đã tồn tại mã dữ liệu này!";
                            e.Valid = false;
                        }
                    }
                    break;
                case GEN_CostSource.C_CostSourceName:
                    e.Valid = Libs.ValidationHelper.ValidateEmptyString(e.Value, "Tên không được bỏ trống!", ref strError);
                    if (e.Valid == true)
                    {
                        if (gvData.SearchRow(GEN_CostSource.C_CostSourceName, e.Value, gvData.FocusedRowHandle) >= 0)
                        {
                            strError = "Đã tồn tên gọi này!";
                            e.Valid = false;
                        }
                    }
                    break;
            }

            if (strError != "")
                e.ErrorText = strError;
        }

        private void gvData_ValidateRow(object sender, DevExpress.XtraGrid.Views.Base.ValidateRowEventArgs e)
        {
            string strError = CheckValidate(gvData.GetFocusedDataRow());
            if (strError != "")
            {
                e.ErrorText = strError;
                e.Valid = false;
            }
            else
                btnSave.Enabled = mnuItemSave.Enabled = true;
        }

        private void gvData_InvalidRowException(object sender, DevExpress.XtraGrid.Views.Base.InvalidRowExceptionEventArgs e)
        {
            e.ExceptionMode = DevExpress.XtraEditors.Controls.ExceptionMode.DisplayError;
        }

        #endregion


    }
}

