/*
	Patch  : GEN_CostSource_ADD
	Date   : 2025-09-18
	Module : General / frmCostSource
	Mô tả  : Thêm nguồn kinh phí — trả về CostSourceID (ExecStoreToString)
*/

Set Ansi_Nulls On
Go
Set Quoted_Identifier On
Go

If Object_Id(N'dbo.GEN_CostSource_ADD', N'P') Is Not Null
	Drop Procedure dbo.GEN_CostSource_ADD
Go

Create Procedure dbo.GEN_CostSource_ADD
(
	@CostSourceCode nvarchar(50),
	@CostSourceName nvarchar(250),
	@Description nvarchar(500),
	@IsDefault bit,
	@IsActived bit,
	@OrderIndex bigint,
	@CreatedUser nvarchar(50)
)
As
Begin
	Set Nocount On;

	Insert Into GEN_CostSource
	(
		CostSourceCode,
		CostSourceName,
		Description,
		IsDefault,
		IsActived,
		OrderIndex,
		CreatedDate,
		CreatedUser
	)
	Values
	(
		@CostSourceCode,
		@CostSourceName,
		@Description,
		@IsDefault,
		@IsActived,
		Isnull(@OrderIndex, 0),
		Getdate(),
		@CreatedUser
	)

	Select Cast(Scope_Identity() As nvarchar(20))
End
Go
